def copy_drivers(apps, schema_editor):
    """
    Transfer.driver/vehicle/driver_* become one TransferDriver (an external
    one if only driver_name was set), TIP transactions get their driver.
    """
    Transfer = apps.get_model('core', 'Transfer')
    TransferDriver = apps.get_model('core', 'TransferDriver')
    Transaction = apps.get_model('core', 'Transaction')
    transfers = Transfer.objects.filter(
        models.Q(driver__isnull=False) | ~models.Q(driver_name__in=['', None])
    )
    TransferDriver.objects.bulk_create([
        TransferDriver(
            transfer_id=transfer.id,
            driver_id=transfer.driver_id,
            vehicle_id=transfer.vehicle_id,
            driver_name=transfer.driver_name or '',
            driver_price=transfer.driver_price,
            driver_price_currency=transfer.driver_price_currency
        )
        for transfer in transfers.iterator()
    ])
    for transfer in Transfer.objects.filter(driver__isnull=False).iterator():
        tips = Transaction.objects.filter(transfer_id=transfer.id, category='TIP')
        tips.update(driver_id=transfer.driver_id)


